import json

def make_hashable(obj):
    if isinstance(obj, dict):
        return ("dict", tuple(sorted((k, make_hashable(v)) for k, v in obj.items())))
    if isinstance(obj, list):
        return ("list", tuple(make_hashable(x) for x in obj))
    if isinstance(obj, tuple):
        return ("tuple", tuple(make_hashable(x) for x in obj))
    if isinstance(obj, set):
        return ("set", tuple(sorted(make_hashable(x) for x in obj)))
    return ("scalar", obj)

def dedupe_preserve_order(items):
    seen = set()
    result = []
    for item in items:
        key = make_hashable(item)
        if key not in seen:
            seen.add(key)
            result.append(item)
    return result

# Demo
data = [
    {"id": 1, "tags": ["a", "b"], "meta": {"score": 10}},
    {"id": 2, "tags": ["x"], "meta": {"score": 5}},
    {"id": 1, "tags": ["a", "b"], "meta": {"score": 10}},  # duplicate
    {"id": 3, "tags": ["x", "y"], "meta": {"score": 5}},
    {"id": 2, "tags": ["x"], "meta": {"score": 5}},        # duplicate
]

deduped = dedupe_preserve_order(data)
print(json.dumps(deduped, indent=2))
